'use strict';
const M=DriftModel, $=id=>document.getElementById(id),fmt=(v,n=1)=>Number(v).toFixed(n).replace('.',','),sgn=(v,n=1)=>(v>0?'+':'')+fmt(v,n);
let state={...M.defaults},view='course',running=true,free=false,lockTrail=false,scene='drift',steerVelocity=0,lastTime=0,phase=0,shockUntil=0,result,lastContactPaint=0,releasedFrom=null;
const definitions=[['ack','Ackermann offset',-9,9,1.5,'мм'],['steer','Steering angle δ',-55,55,.5,'°'],['beta','Drift angle β',-55,55,1,'°'],['speed','Speed',5,110,1,'км/ч'],['yaw','Yaw rate r',-40,40,1,'°/с'],['camber','Static camber',-8,2,.1,'°'],['caster','Caster',0,15,.5,'°'],['trail','Mechanical trail',-10,100,1,'мм'],['kpi','KPI / SAI',0,20,.5,'°'],['scrub','Scrub radius',-50,100,1,'мм'],['rc','Front roll center',-50,200,5,'мм'],['damping','Steering damping',1,20,.5,'Н·м·с/рад'],['mu','Friction coefficient μ',.4,1.5,.05,''],['wheelbase','Wheelbase',2300,3100,10,'мм'],['track','Front track width',1400,1900,10,'мм'],['steeringArm','Steering arm length',60,180,5,'мм'],['tyreWidth','Tire width',185,285,10,'мм'],['tyreAspect','Aspect ratio',30,65,5,'%'],['rimDiameter','Rim diameter',15,20,1,'дюйм'],['tyrePressure','Tire pressure',1.4,3,.1,'бар'],['tyreCompliance','Contact compliance',.5,2,.1,'×'],['springRate','Front spring rate',4,20,.5,'kgf/mm'],['motionRatio','Motion ratio',.65,1.05,.01,'×'],['frontBarRate','Front ARB roll stiffness',0,50,1,'kN·m/rad'],['wheelTravelLF','Wheel input LF',-50,50,1,'мм'],['wheelTravelRF','Wheel input RF',-50,50,1,'мм'],['bumpToe','Bump toe (+25 mm)',-1,1,.025,'°'],['reboundToe','Rebound toe (−25 mm)',-1,1,.025,'°']];
const hints={springRate:'Жёсткость одной передней пружины. 1 kgf/mm = 9,80665 N/mm. Исходные 8 kgf/mm — условная настройка.',motionRatio:'Ход пружины / ход колеса, включая установленный угол. Wheel rate = Spring rate × Motion ratio².',frontBarRate:'Добавка стабилизатора к жёсткости передней оси на крен, уже приведённая к кузову. Это не паспортная жёсткость самого торсиона.',wheelTravelLF:'Дополнительный заданный ход левого колеса относительно кузова. «+» — сжатие, «−» — отбой. При включённом Body roll суммируется с ходом от крена.',wheelTravelRF:'Дополнительный заданный ход правого колеса относительно кузова. «+» — сжатие, «−» — отбой. Ручной ход — кинематическая проверка, а не удар с рассчитанной силой.',bumpToe:'Изменение схождения одного колеса при сжатии на 25 мм. «+» — toe-in, «−» — toe-out. Введите измерение; начальная нулевая кривая не описывает конкретную машину.',reboundToe:'Изменение схождения одного колеса при отбое на 25 мм. Вместе с точкой сжатия задаёт учебную кривую. Реальная кривая может меняться на вывороте.',tyrePressure:'Давление в модели, без поправки на нагрев. 2,2 бар — исходное допущение, не рекомендация для трека.',tyreCompliance:'Условный коэффициент упругости: выше — больше деформация и компенсация наклона протектора. Не измеренная жёсткость вашей шины.',ack:'0 мм — нулевой Аккерман в модели. Минус — внутрь, к центру машины; плюс — наружу. Одинаковое смещение на обоих кулаках, шаг 1,5 мм. Схождение после перестановки считается восстановленным.',steeringArm:'Расстояние вперёд / назад от оси поворота до точки тяги, в плане. По умолчанию 100 мм — условный кулак.',steer:'Эквивалентный центральный угол, не угол рулевого колеса. «+» — налево.',beta:'Направление скорости относительно кузова. Для левого заноса обычно β < 0, контрруление δ < 0.',yaw:'Скорость разворота кузова в плане, вид сверху, в °/с. Это не Body roll: крен измеряется в ° и рассчитывается через боковое ускорение и жёсткость. «+» — левый поворот.',caster:'При неизменном смещении ступицы кастер меняет и trail. Включите фиксацию ниже, чтобы разделить эффекты.',trail:'Продольное плечо при прямых колёсах. Меняется независимо через положение ступицы относительно оси поворота.',kpi:'Наклон оси поворота внутрь во фронтальной проекции. На вывороте обычно добавляет положительный развал.',scrub:'Поперечное плечо при прямых колёсах. «+» — центр пятна снаружи пересечения оси с дорогой.',rc:'Условная высота переднего центра крена. Геометрия рычагов в реальной машине задаёт её совместно с другими параметрами.'};

function ackType(s){const a=s.ack*s.rackSide;return a>0?'Positive':a<0?'Reverse':'Zero'}
function offsetLabel(d){return d===0?'Ноль · 0 мм':fmt(Math.abs(d))+' мм '+(d<0?'внутрь':'наружу')}
function mountDiagram(){const x0=137,y0=95-state.rackSide*43,x=x0-state.ack*4.5;return `<svg viewBox="0 0 270 185" role="img" aria-label="Смещение точки тяги на левом кулаке: ${offsetLabel(state.ack)}"><text x="8" y="17" fill="#99a7b2" font-size="11">Левый кулак · вид сверху · перед сверху</text><rect x="70" y="64" width="22" height="63" rx="4" fill="#22372a" stroke="#638159"/><path d="M137 95L${x0} ${y0}" stroke="#708291" stroke-dasharray="4 4"/><circle cx="${x0}" cy="${y0}" r="7" fill="none" stroke="#99a7b2" stroke-dasharray="2 2"/><path d="M137 95L${x} ${y0}" stroke="#c6f36b" stroke-width="4"/><path d="M253 ${y0}L${x} ${y0}" stroke="#65d8ef" stroke-width="2"/><circle cx="137" cy="95" r="6" fill="#edf2f4"/><circle cx="${x}" cy="${y0}" r="5" fill="#c6f36b"/><text x="148" y="99" fill="#99a7b2" font-size="10">Steering axis</text><text x="205" y="${y0-8}" fill="#65d8ef" font-size="11">Tie rod</text><text x="8" y="155" fill="#99a7b2" font-size="11">Наружу</text><text x="259" y="155" text-anchor="end" fill="#99a7b2" font-size="11">Внутрь</text><text x="135" y="176" text-anchor="middle" fill="#c6f36b" font-size="13">${offsetLabel(state.ack)} · ${ackType(state)}</text></svg><p class="control-hint">Пунктир — нулевая точка. Смещения на схеме увеличены.</p>`}

function alignmentButtons(){return '<div class="alignment-presets">'+[[4,-3],[5.5,-4],[6.5,-5]].map(([c,g])=>`<button data-alignment-caster="${c}" data-alignment-camber="${g}" aria-pressed="${state.caster===c&&state.camber===g}">Caster ${fmt(c,c%1?1:0)}° · Camber ${fmt(g,0)}°</button>`).join('')+'</div>'}
function kpiButtons(){return '<div class="kpi-presets" aria-label="KPI: варианты для сравнения">'+[12,10,8].map(v=>`<button data-kpi-preset="${v}" aria-pressed="${state.kpi===v}">KPI ${v}°</button>`).join('')+'</div>'}
function control(d){let[k,label,min,max,step,unit]=d;return `<div class="control"><div class="control-top"><label for="${k}">${label}</label><span><input aria-label="${label}: значение" class="number-entry" id="${k}-number" type="number" min="${min}" max="${max}" step="${step}" value="${state[k]}"> <span class="unit">${unit}</span></span></div><input id="${k}" type="range" min="${min}" max="${max}" step="${step}" value="${state[k]}"><div class="endpoints"><span>${k==='ack'?'Внутрь −9 мм':min}</span><span>${k==='ack'?'Наружу +9 мм':max}</span></div>${hints[k]?`<p class="control-hint">${hints[k]}</p>`:''}${k==='kpi'?kpiButtons():''}${k==='trail'?'<label class="link-option"><input type="checkbox" id="lock-trail"> Сохранять trail при смене кастера</label><p id="offset-note" class="control-hint"></p>':''}</div>`}
$('controls').innerHTML=`<div class="control-section"><p class="control-title">Рулевая геометрия</p><div class="ack-buttons"><button data-ack-step="-1">Внутрь 1,5</button><button class="active" data-ack="0">Ноль</button><button data-ack-step="1">Наружу 1,5</button></div>${control(definitions[0])}<label class="control-top" for="steering-side">Steering arm position</label><select id="steering-side"><option value="1">Перед осью колёс</option><option value="-1">За осью колёс</option></select><div id="ack-mount-diagram"></div><p class="control-hint">Схема и миллиметры относятся к условной геометрии. Углы конкретного комплекта зависят также от рейки и длины тяг.</p>${control(definitions[1])}</div><div class="control-section"><p class="control-title">Состояние заноса</p>${definitions.slice(2,5).map(control).join('')}</div><div class="control-section"><p class="control-title">Развал и самоповорот</p>${definitions.slice(5,8).map(control).join('')}</div><div class="control-section"><p class="control-title">Ось поворота и крен</p>${definitions.slice(8,11).map(control).join('')}</div><div class="control-section"><p class="control-title">Шины и рулевой механизм</p>${definitions.slice(11,13).map(control).join('')}<button id="shock">Толчок в правое колесо</button><p class="control-hint">Продольная сила 1 кН на RF в течение 0,35 с. Сравните реакцию при разном радиусе обката.</p></div><div class="control-section"><p class="control-title">Размеры машины</p>${definitions.slice(13,16).map(control).join('')}</div><div class="control-section"><p class="control-title">Шина и пятно контакта</p>${definitions.slice(16,21).map(control).join('')}</div><div class="control-section"><p class="control-title">Front suspension stiffness</p>${definitions.slice(21,24).map(control).join('')}</div><div class="control-section"><p class="control-title">Bump steer</p>${definitions.slice(24).map(control).join('')}<label class="link-option"><input type="checkbox" id="bump-roll-sidebar"> Учитывать ход от Body roll</label></div>`;
function sync(){$('bump-roll-sidebar').checked=!!state.bumpFromRoll;document.querySelectorAll('[data-alignment-caster]').forEach(b=>{const active=state.caster===+b.dataset.alignmentCaster&&state.camber===+b.dataset.alignmentCamber;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});document.querySelectorAll('[data-kpi-preset]').forEach(b=>{b.classList.toggle('active',state.kpi===+b.dataset.kpiPreset);b.setAttribute('aria-pressed',state.kpi===+b.dataset.kpiPreset)});$('patch-steer').value=state.steer;$('patch-steer-value').textContent=sgn(state.steer)+'°';if(document.activeElement!==$('patch-pressure'))$('patch-pressure').value=state.tyrePressure;for(const d of definitions){$(d[0]).value=state[d[0]];if(document.activeElement!==$(d[0]+'-number'))$(d[0]+'-number').value=Math.round(state[d[0]]*100)/100}document.querySelectorAll('[data-ack]').forEach(b=>b.classList.toggle('active',state.ack===+b.dataset.ack));document.querySelectorAll('[data-scene]').forEach(b=>b.classList.toggle('active',scene===b.dataset.scene));$('steering-side').value=state.rackSide;document.querySelectorAll('[data-ack-step]').forEach(b=>{b.disabled=state.ack+(+b.dataset.ackStep)*1.5< -9||state.ack+(+b.dataset.ackStep)*1.5>9});$('ack-mount-diagram').innerHTML=mountDiagram();$('lock-trail').checked=lockTrail;$('offset-note').textContent=`Эквивалентное смещение ступицы: ${fmt(M.tyreRadius(state)*Math.tan(state.caster*M.rad)-state.trail)} мм.`}
function setValue(key,value){if(key==='bumpFromRoll'){if(![0,1].includes(value))throw Error('Invalid roll link');state.bumpFromRoll=value;sync();render();return}if(key==='rackSide'){if(![-1,1].includes(value))throw Error('Некорректная сторона рычага');state.rackSide=value;sync();render();return}const d=definitions.find(d=>d[0]===key);if(!d||!Number.isFinite(value))throw Error('Некорректный параметр');const next=key==='ack'?Math.round(M.clamp(value,d[2],d[3])/1.5)*1.5:M.clamp(value,d[2],d[3]);if(key==='caster'&&!lockTrail)state.trail=M.clamp(state.trail+M.tyreRadius(state)*(Math.tan(next*M.rad)-Math.tan(state.caster*M.rad)),-10,100);state[key]=next;if(key==='steer'){free=false;steerVelocity=0}if(['beta','yaw','steer'].includes(key)&&scene==='transition')scene='custom';sync();render()}
for(const d of definitions)for(const id of [d[0],d[0]+'-number']){$(id).addEventListener('input',e=>{if(e.target.value!=='')setValue(d[0],+e.target.value)});$(id).addEventListener('change',()=>{if(id.endsWith('-number'))$(id).value=Math.round(state[d[0]]*100)/100})}
$('patch-steer').oninput=e=>setValue('steer',+e.target.value);
$('patch-pressure').oninput=e=>{if(e.target.value!=='')setValue('tyrePressure',+e.target.value)};
$('patch-pressure').onchange=()=>{$('patch-pressure').value=state.tyrePressure};
$('bump-roll-sidebar').onchange=e=>setValue('bumpFromRoll',e.target.checked?1:0);
$('lock-trail').onchange=e=>{lockTrail=e.target.checked;sync()};
document.querySelectorAll('[data-ack]').forEach(b=>b.onclick=()=>setValue('ack',+b.dataset.ack));
document.querySelectorAll('[data-ack-step]').forEach(b=>b.onclick=()=>setValue('ack',state.ack+(+b.dataset.ackStep)*1.5));
$('steering-side').onchange=e=>setValue('rackSide',+e.target.value);
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});
function setScene(name){scene=name;free=false;steerVelocity=0;phase=0;running=true;if(name==='parking'){state.beta=Math.atan(.55*Math.tan(20*M.rad))*M.deg;state.steer=20;state.speed=8;state.yaw=(state.speed/3.6*Math.cos(state.beta*M.rad))*Math.tan(20*M.rad)/(state.wheelbase/1000)*M.deg}else{state.beta=-32;state.steer=-28;state.speed=65;state.yaw=18}sync();render()}
document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>setScene(b.dataset.scene));
$('reset').onclick=()=>{state={...M.defaults};lockTrail=false;view='course';setScene('drift')};
$('animate').onclick=()=>{running=!running;render()};
$('release').onclick=()=>{free=!free;if(free)releasedFrom=state.steer;steerVelocity=0;running=true;render()};
$('shock').onclick=()=>{shockUntil=performance.now()+350;running=true;render()};
const colors={lime:'#c6f36b',cyan:'#65d8ef',orange:'#ffa66b',muted:'#99a7b2'};
function arrow(x,y,dx,dy,color,width=2,dashed=false){return `<path d="M${x} ${y}l${dx} ${dy}" stroke="${color}" stroke-width="${width}" ${dashed?'stroke-dasharray="7 8" class="rolling"':''} fill="none" marker-end="url(#arr-${color.slice(1)})"/>`}
function svgStart(label){return `<svg viewBox="0 0 820 480" role="img" aria-label="${label}"><defs><pattern id="grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M35 0H0V35" fill="none" stroke="#27353e" stroke-width=".6"/></pattern>${Object.values(colors).map(c=>`<marker id="arr-${c.slice(1)}" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto-start-reverse"><path d="M0 0L6 3L0 6Z" fill="${c}"/></marker>`).join('')}</defs><rect width="820" height="480" fill="url(#grid)"/>`}
function topView(r){const sc=87,L=state.wheelbase/1000,T=state.track/1000,cy=255,frontY=cy-L*.45*sc,rearY=cy+L*.55*sc,px=y=>410-y*sc;
 let h=svgStart('Вид сверху: углы колёс, локальная скорость, угол увода и боковые силы');
 h+=`<text x="28" y="36" fill="#c6f36b" font-size="13" letter-spacing="1">${ackType(state).toUpperCase()} ACKERMANN / ${offsetLabel(state.ack).toUpperCase()}</text><text x="28" y="60" fill="#99a7b2" font-size="12">${free?'Руль свободен · движение кузова задано':'Руль удерживается · направление скорости задано'}</text>`;
 const vb=state.beta*M.rad;for(let i=0;i<7;i++){const x=75+i*111,y=90+(i%2)*140;h+=arrow(x,y,Math.sin(vb)*75,Math.cos(vb)*75,'#99a7b2',.7,true)}
 h+=`<path d="M350 ${frontY-45}Q410 ${frontY-72}470 ${frontY-45}L482 ${rearY+29}Q410 ${rearY+50}338 ${rearY+29}Z" fill="#1c2b36" stroke="#566d7d" stroke-width="2"/><path d="M360 ${frontY+25}H460L471 ${frontY+82}H349Z" fill="#101c26" stroke="#345164"/><path d="M358 ${rearY-65}H462L454 ${rearY-26}H366Z" fill="#101c26" stroke="#345164"/><path d="M410 ${frontY-52}V${rearY+39}" stroke="#4b6474" stroke-dasharray="5 6"/><text x="410" y="${frontY+113}" text-anchor="middle" fill="#597181" font-size="12" letter-spacing="3">MACPHERSON</text>`;
 h+=`<path d="M${px(T/2)} ${frontY}H${px(-T/2)}M${px(T/2)} ${rearY}H${px(-T/2)}" stroke="#667f8f" stroke-width="3"/>`;
 for(const w of r.wheels){let x=px(w.side*T/2),d=w.delta*M.rad,b=w.direction*M.rad;
 h+=`<circle cx="${x}" cy="${frontY}" r="64" fill="none" stroke="#283e4b" stroke-dasharray="3 7"/>`;
 h+=arrow(x,frontY,-Math.sin(b)*118,-Math.cos(b)*118,colors.cyan,2.5,true);
 h+=`<path d="M${x+Math.sin(d)*60} ${frontY+Math.cos(d)*60}L${x-Math.sin(d)*88} ${frontY-Math.cos(d)*88}" stroke="#c6f36b" opacity=".55" stroke-dasharray="6 6"/><g transform="translate(${x},${frontY}) rotate(${-w.delta})"><rect x="-14" y="-32" width="28" height="64" rx="5" fill="#293c25" stroke="#c6f36b" stroke-width="2.5"/><path d="M-8 -23H8M-8 -13H8M-8 -3H8M-8 7H8M-8 17H8M-8 25H8" stroke="#769852" stroke-width="1"/></g>`;
 h+=arrow(x,frontY,-Math.cos(d)*w.Fy/55,Math.sin(d)*w.Fy/55,colors.orange,3);
 const labelX=w.side===1?125:584;
 h+=`<text x="${labelX}" y="${frontY-2}" fill="#c6f36b" font-size="23" font-weight="600">${w.name} ${sgn(w.delta)}°</text><text x="${labelX}" y="${frontY+24}" fill="#65d8ef" font-size="14">Slip angle α ${sgn(w.alpha)}°</text><text x="${labelX}" y="${frontY+48}" fill="#99a7b2" font-size="13">Wheel load ${fmt(w.Fz/9.81,0)} кгс</text><rect x="${labelX}" y="${frontY+60}" width="107" height="4" rx="2" fill="#273843"/><rect x="${labelX}" y="${frontY+60}" width="${107*w.Fz/(1250*9.81*.55)}" height="4" rx="2" fill="#65d8ef"/>`;
 h+=`<rect x="${x-14}" y="${rearY-30}" width="28" height="60" rx="5" fill="#142029" stroke="#6c8494" stroke-width="2"/>`}
 h+=`<circle cx="410" cy="${cy}" r="5" fill="#e7eef3"/>`+arrow(410,cy,-Math.sin(vb)*135,-Math.cos(vb)*135,colors.cyan,3);
 h+=`<text x="${410-Math.sin(vb)*144}" y="${cy-Math.cos(vb)*144}" fill="#65d8ef" font-size="14">V ${fmt(state.speed,0)} км/ч</text><text x="28" y="431" fill="#edf2f4" font-size="17">β ${sgn(state.beta)}° <tspan fill="#7e95a4"> / </tspan> r ${sgn(state.yaw)}°/с</text><text x="28" y="455" fill="#99a7b2" font-size="12">Вектор скорости каждого колеса учитывает вращение кузова</text><text x="785" y="431" text-anchor="end" fill="#c6f36b" font-size="16">${r.torque>1?'↶ влево':r.torque< -1?'вправо ↷':'равновесие'}</text><text x="785" y="455" text-anchor="end" fill="#99a7b2" font-size="12">Направление момента на рулевом механизме</text></svg>`;return h}
function suspensionView(r){let h=svgStart('Схема МакФерсона: стойка, шаровая, ось поворота, KPI, кастер, trail и радиус обката');const X=y=>224-y*.205,Z=z=>347-z*.31;
 h+=`<text x="25" y="32" fill="#edf2f4" font-size="17">Фронтальная схема · прямые колёса</text><text x="25" y="56" fill="#99a7b2" font-size="12">Смотрим по ходу движения. Конструкция схематическая.</text><path d="M25 347H425" stroke="#7b8e9b"/><path d="M224 87V371" stroke="#415666" stroke-dasharray="5 5"/><path d="M100 122H348" stroke="#5d7587" stroke-width="9"/>`;
 for(const side of [1,-1]){let t=state.track/2,sy=t-state.scrub,ty=sy-650*Math.tan(state.kpi*M.rad),by=sy-180*Math.tan(state.kpi*M.rad),hy=ty+320*Math.tan(16*M.rad),m=Math.tan(16*M.rad),icy=(state.rc-650+m*ty)/(m+state.rc/t),icz=state.rc-state.rc/t*icy,iy=330,iz=180+(iy-by)*(icz-180)/(icy-by);
 const sx=y=>X(side*y);h+=`<path d="M${sx(sy)} 347L${sx(ty)} ${Z(650)}" stroke="#ffa66b" stroke-width="1.8" stroke-dasharray="6 4"/><path d="M${sx(ty)} ${Z(650)}L${sx(hy)} ${Z(330)}" stroke="#94a8b6" stroke-width="8"/><path d="M${sx(ty)} ${Z(640)}L${sx(hy)} ${Z(340)}" stroke="#c6f36b" stroke-width="16" stroke-dasharray="4 12"/><path d="M${sx(hy)} ${Z(330)}L${sx(by)} ${Z(180)}L${sx(iy)} ${Z(iz)}" stroke="#8ca4b5" stroke-width="5"/><circle cx="${sx(by)}" cy="${Z(180)}" r="6" fill="#ffa66b"/><circle cx="${sx(ty)}" cy="${Z(650)}" r="6" fill="#c6f36b"/><circle cx="${sx(iy)}" cy="${Z(iz)}" r="5" fill="#8ca4b5"/><g transform="translate(${sx(t)},${Z(155)}) rotate(${-side*state.camber})"><rect x="-12" y="-46" width="24" height="92" rx="4" fill="#273c24" stroke="#c6f36b" stroke-width="2"/></g><path d="M${sx(t)} 347L224 ${Z(state.rc)}" stroke="#65d8ef" stroke-width="1.5" stroke-dasharray="5 4"/><path d="M${sx(t)} 363H${sx(sy)}" stroke="#ffa66b" stroke-width="3"/>`}
 h+=`<circle cx="224" cy="${Z(state.rc)}" r="6" fill="#65d8ef"/><text x="235" y="${Z(state.rc)-9}" fill="#65d8ef" font-size="13">RC ${state.rc} мм</text><text x="30" y="92" fill="#ffa66b" font-size="14">KPI ${fmt(state.kpi)}°</text><text x="28" y="389" fill="#ffa66b" font-size="13">Scrub radius: ${sgn(state.scrub,0)} мм</text><text x="28" y="412" fill="#99a7b2" font-size="12">Roll moment arm / CG − RC: ${fmt(520-state.rc,0)} мм</text><text x="28" y="437" fill="#99a7b2" font-size="12">Рычаг и стойка задают мгновенный центр;</text><text x="28" y="455" fill="#99a7b2" font-size="12">линия «пятно — мгновенный центр» задаёт RC.</text>`;
 const cx=635,ground=282,scale=.28,axisGround=cx+state.trail*scale,topX=axisGround-650*Math.tan(state.caster*M.rad)*scale;
 h+=`<path d="M450 75V455" stroke="#283945"/><text x="480" y="32" fill="#edf2f4" font-size="17">Сбоку · перед машины справа</text><text x="480" y="57" fill="#99a7b2" font-size="12">Caster — угол. Trail — расстояние на дороге.</text><path d="M475 ${ground}H790" stroke="#7b8e9b"/><circle cx="${cx}" cy="${ground-M.tyreRadius(state)*scale}" r="${M.tyreRadius(state)*scale}" fill="#1b2b36" stroke="#718b9e" stroke-width="3"/><circle cx="${cx}" cy="${ground-M.tyreRadius(state)*scale}" r="52" fill="#142029" stroke="#3b5567"/><path d="M${axisGround} ${ground}L${topX} ${ground-650*scale}" stroke="#ffa66b" stroke-width="3" stroke-dasharray="7 5"/><path d="M${topX} ${ground-650*scale}V${ground-650*scale+100}" stroke="#536773" stroke-dasharray="4 5"/><circle cx="${axisGround}" cy="${ground}" r="5" fill="#ffa66b"/><circle cx="${cx}" cy="${ground}" r="5" fill="#c6f36b"/><path d="M${cx} ${ground+17}H${axisGround}" stroke="#c6f36b" stroke-width="3"/><text x="480" y="310" fill="#c6f36b" font-size="14">Mechanical trail ${fmt(state.trail)} мм · Caster ${fmt(state.caster)}°</text><text x="480" y="338" fill="#edf2f4" font-size="13">Dynamic camber · к дороге на вывороте</text>`;
 h+=`<path d="M505 368H755" stroke="#506471" stroke-dasharray="4 5"/><g transform="rotate(${r.roll*4},630,368)"><rect x="520" y="356" width="220" height="24" rx="6" fill="#334958" stroke="#a2b6c5" stroke-width="2"/><path d="M577 356L590 345H670L683 356" fill="#1b2a35" stroke="#a2b6c5"/></g><text x="630" y="532" text-anchor="middle" fill="#65d8ef" font-size="12">Body roll φ ${sgn(r.roll)}° · наклон кузова ×4</text>`;
 for(const [i,w] of r.wheels.entries()){let x=550+i*157;h+=`<path d="M${x-37} 469H${x+37}" stroke="#536d7e"/><g transform="translate(${x},436) rotate(${-w.side*w.camber})"><rect x="-12" y="-33" width="24" height="66" rx="3" fill="#263b23" stroke="#c6f36b" stroke-width="2"/></g><text x="${x}" y="499" text-anchor="middle" fill="${Math.abs(w.camber)>5?'#ffa66b':'#c6f36b'}" font-size="15">${w.name} ${sgn(w.camber)}°</text>`}return '<div class="suspension-grid">'+(h+'</svg>').replace('viewBox="0 0 820 480"','viewBox="0 0 450 480"').replace('<path d="M450 75V455" stroke="#283945"/>','</svg><svg viewBox="450 0 370 540" role="img" aria-label="Caster, Mechanical trail и Dynamic camber">')+'</div>'}
function renderSuspension(r){
 const template=document.createElement('template');template.innerHTML=suspensionView(r);const diagrams=template.content.querySelectorAll('svg');
 if(!$('suspension-steer')){
  $('stage').innerHTML='<div class="suspension-grid suspension-live"><div id="suspension-front"></div><div class="suspension-right"><div id="suspension-side"></div><div class="suspension-steering"><div class="control-top"><label for="suspension-steer">Steering angle δ</label><span><input id="suspension-steer-number" class="number-entry" type="number" min="-55" max="55" step="0.5" aria-label="Steering angle на схеме: значение"> °</span></div><input id="suspension-steer" aria-label="Steering angle на схеме" type="range" min="-55" max="55" step="0.5"><div class="endpoints"><span>Вправо −55°</span><span>Влево +55°</span></div><div class="suspension-steer-actions"><button id="suspension-straight">Steering angle 0°</button><button id="suspension-static">Проверить Static camber</button><button id="suspension-contact">Contact patch ↗</button></div><p id="suspension-wheel-angles"></p><p id="suspension-patch-areas"></p><p id="suspension-camber-components"></p><p class="control-hint">Steering angle 0° обнуляет центральный угол; крен и Bump steer сохраняются. «Проверить Static camber» убирает выворот, боковое ускорение и заданный ход колёс.</p></div></div></div>';
  $('suspension-steer').oninput=e=>setValue('steer',+e.target.value);
  $('suspension-steer-number').oninput=e=>{if(e.target.value!=='')setValue('steer',+e.target.value)};
  $('suspension-steer-number').onchange=()=>{$('suspension-steer-number').value=Math.round(state.steer*100)/100};
  $('suspension-straight').onclick=()=>setValue('steer',0);$('suspension-static').onclick=()=>{free=false;steerVelocity=0;running=false;scene='custom';Object.assign(state,{steer:0,beta:0,yaw:0,wheelTravelLF:0,wheelTravelRF:0});resetPose();sync();render()};
  $('suspension-contact').onclick=()=>{view='contact';render()};
 }
 $('suspension-front').innerHTML=diagrams[0].outerHTML;$('suspension-side').innerHTML=diagrams[1].outerHTML;
 $('suspension-steer').value=state.steer;if(document.activeElement!==$('suspension-steer-number'))$('suspension-steer-number').value=Math.round(state.steer*100)/100;
 $('suspension-camber-components').textContent='Body roll '+sgn(r.roll)+'° → Camber contribution LF '+sgn(r.wheels[0].rollCamberDelta)+'° / RF '+sgn(r.wheels[1].rollCamberDelta)+'°';
 $('suspension-wheel-angles').textContent='Steering angle LF '+sgn(r.wheels[0].delta)+'° / RF '+sgn(r.wheels[1].delta)+'°';
 $('suspension-patch-areas').textContent='Contact area LF '+fmt(M.contactPatch(state,r.wheels[0]).areaCm2,0)+' / RF '+fmt(M.contactPatch(state,r.wheels[1]).areaCm2,0)+' см² · оценка';
}
function compareView(){return `<div class="compare-wrap"><div class="compare-grid">${[-1.5,0,1.5].map(A=>{let s={...state,ack:A},r=M.calculate(s);return `<div class="compare-card ${state.ack===A?'current':''}"><h3>${offsetLabel(A)} <span class="muted">· ${ackType(s)}</span></h3><svg viewBox="0 0 200 150" role="img" aria-label="Колёса при смещении точки тяги ${A} мм"><path d="M35 77H165" stroke="#566d7d" stroke-width="3"/>${r.wheels.map((w,i)=>`<g transform="translate(${35+i*130},77) rotate(${-w.delta})"><path d="M0 -62V60" stroke="#8cb74f" stroke-dasharray="5 4"/><rect x="-11" y="-28" width="22" height="56" rx="4" fill="#293c25" stroke="#c6f36b" stroke-width="2"/></g><text x="${35+i*130}" y="145" text-anchor="middle" fill="#d9e7ed" font-size="13">${fmt(w.delta)}°</text>`).join('')}</svg><p>Slip angle LF / RF<br><strong>${sgn(r.wheels[0].alpha)}° / ${sgn(r.wheels[1].alpha)}°</strong><br>Load-weighted slip: ${fmt(r.weightedSlip)}°<br>Steering torque: ${sgn(r.torque,0)} Н·м</p><button data-compare="${A}">Применить</button></div>`}).join('')}</div><p class="compare-caption">Сравнение одного шага внутрь, нуля и одного шага наружу. Одинаковые выворот, скорость, β и вращение кузова. Сравнивайте увод обоих колёс с учётом нагрузки. Меньший увод сам по себе не означает больше боковой силы: шине нужен рабочий угол увода.</p><p class="compare-caption">«Внутреннее» в определении Аккермана — по направлению руления. В контррулении это может быть внешнее, более нагруженное колесо по траектории машины.</p></div>`}
function metric(label,value,note,color=''){return `<div class="metric"><span class="label">${label}</span><b ${color?`style="color:${color}"`:''}>${value}</b><small>${note}</small></div>`}
function renderSetup(r){$('live-setup').innerHTML=`<div class="setup-grid"><div><span>Ackermann offset</span><strong>${sgn(state.ack)} <small>мм</small></strong><p>${ackType(state)} Ackermann · ${state.ack===0?'нулевая точка':state.ack>0?'наружу':'внутрь'}</p></div><div><span>Static camber</span><strong>${sgn(state.camber)}°</strong><p>Заданный статический развал</p></div><div><span>Caster</span><strong>${fmt(state.caster)}°</strong><p>KPI ${fmt(state.kpi)}° · Trail ${fmt(state.trail,0)} мм</p></div><div><span>Body roll φ</span><strong>${sgn(r.roll)}°</strong><p>Наклон кузова вбок · расчёт</p></div></div><div class="setup-wheel-values"><span><b>Yaw rate r</b> ${sgn(state.yaw)}°/с · разворот в плане</span><span><b>Steering angle</b> LF ${sgn(r.wheels[0].delta)}° / RF ${sgn(r.wheels[1].delta)}°</span><span><b>Dynamic camber</b> LF ${sgn(r.wheels[0].camber)}° / RF ${sgn(r.wheels[1].camber)}°</span></div>`}
function render(){result=M.calculate(state,performance.now()<shockUntil?1000:0);const r=result,loaded=r.wheels[0].Fz>r.wheels[1].Fz?r.wheels[0]:r.wheels[1];renderSetup(r);renderSelfSteer(r);document.body.classList.toggle('paused',!running);$('animate').textContent=running?'Пауза':'Продолжить';$('animate').setAttribute('aria-pressed',running);$('release').textContent=free?'Удерживать руль':'Отпустить руль';$('release').setAttribute('aria-pressed',free);document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-selected',b.dataset.view===view));$('view-caption').textContent=view==='suspension'?'Геометрия и положение колеса':'LF / RF — со стороны водителя';
 if(view==='suspension')renderSuspension(r);else if(view==='bump')renderBump(r);else $('stage').innerHTML=view==='top'?topView(r):view==='compare'?compareView():'';document.querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>setValue('ack',+b.dataset.compare));
 $('metrics').innerHTML=metric('Steering angle difference',fmt(Math.abs(r.wheels[state.steer>=0?0:1].delta)-Math.abs(r.wheels[state.steer>=0?1:0].delta))+'°','Внутреннее − внешнее; с Bump steer')+metric(`Camber · loaded ${loaded.name}`,sgn(loaded.camber)+'°','К дороге, с выворотом и креном',Math.abs(loaded.camber)>5?'#ffa66b':'#c6f36b')+metric('Steering torque',sgn(r.torque,0)+' Н·м','Условный, приведён к δ; «+» влево')+metric('Body roll',sgn(r.roll)+'°',`Задано aᵧ = ${sgn(r.ay/9.81,2)} g`);
 let ackText=state.ack*state.rackSide>0?'Положительный Аккерман увеличивает выворот внутреннего по рулению колеса.':state.ack*state.rackSide<0?'Обратный Аккерман увеличивает выворот внешнего по рулению колеса.':'Zero Ackermann задаёт одинаковые базовые углы. Bump steer может добавить разницу; углы увода тоже могут различаться.';
 let advice=Math.abs(loaded.camber)<1?'Колесо близко к вертикали — геометрически хороший ориентир для пятна контакта.':loaded.camber>0?'Верх колеса наклонён наружу. Дополнительный статический минус либо меньшие кастер / KPI могут приблизить колесо к вертикали при этом контррулении.':'Колесо сохраняет отрицательный развал. Избыток минуса тоже сокращает эффективное пятно; проверяйте весь диапазон выворота.';
 $('insight').innerHTML=`<strong>${ackText}</strong> Сейчас больше нагружено ${loaded.name}: развал ${sgn(loaded.camber)}°. ${advice}${r.overDemand?'<br><span class="warning">Заданное боковое ускорение превышает μg. Такой режим может быть недостижим: модель не решает равновесие всей машины.</span>':''}${r.lift?'<br><span class="warning">Расчёт предсказывает разгрузку одного колеса до нуля. Линейная модель крена за пределами применимости.</span>':''}${free?'<br>Самоповорот ищет баланс моментов при заданном движении кузова; руль не обязан возвращаться в ноль.':''}`;
 $('detail').innerHTML=`<div class="detail-top"><h2>Что происходит с передними колёсами</h2><span class="detail-note">Силы и моменты — иллюстративные</span></div><div class="table-scroll"><table><thead><tr><th>Wheel</th><th>Steering angle δ</th><th>Slip angle α</th><th>Camber γ</th><th>Wheel load</th><th>Lateral force Fᵧ</th></tr></thead><tbody>${r.wheels.map(w=>`<tr><td>${w.name}${w===loaded?' ●':''}</td><td>${sgn(w.delta)}°</td><td>${sgn(w.alpha)}°</td><td>${sgn(w.camber)}°</td><td>${fmt(w.Fz/1000,2)} кН</td><td>${sgn(w.Fy/1000,2)} кН</td></tr>`).join('')}</tbody></table></div><div class="moment-bar"><span>Mechanical trail torque: ${sgn(r.mt,0)} Н·м</span><span>Pneumatic trail torque: ${sgn(r.mp,0)} Н·м</span><span>Jacking torque: ${sgn(r.mj,0)} Н·м</span>${r.mx?`<span class="warning">Kickback torque: ${sgn(r.mx,0)} Н·м</span>`:''}</div><p class="control-hint">Эффективное плечо боковой силы на вывороте LF / RF: ${fmt(r.wheels[0].mechTrail*1000)} / ${fmt(r.wheels[1].mechTrail*1000)} мм. Оно отличается от trail при прямых колёсах. Чувствительность RF к продольной силе: ${sgn(r.kick,0)} Н·м на 1 кН.</p><p class="control-hint">Перенос нагрузки на внешнее колесо: геометрический ${fmt(Math.abs(r.geom)/1000,2)} кН + упругий ${fmt(Math.abs(r.elastic)/1000,2)} кН. Нагрузка переносится с одного колеса на другое, а не создаётся заново.</p>`;
}
const lessons=[
 ['01','Ackermann · шаг 1,5 мм','Положительный: внутреннее по рулению колесо поворачивается сильнее. Нулевой: базовые углы одинаковы. Обратный: сильнее поворачивается внешнее. Bump steer добавляется к этим углам отдельно. Trailing меняет общую силу передней оси: передок может охотнее идти вперёд или двигаться боком. Итоговый баланс определяет вся машина.','Начните с 0 мм и двигайте точку тяги симметрично на обоих кулаках по 1,5 мм. Для рычага перед осью движение наружу даёт положительный Аккерман в модели; для рычага за осью — наоборот.','Сравнить −1,5 / 0 / +1,5 мм','ack'],
 ['02','Caster ↔ Static camber','В контррулении нагруженное по траектории колесо может получать положительную добавку развала от кастера. Чем больше кастер, тем больше статического минуса может понадобиться, чтобы поставить это колесо ровно на рабочем вывороте.','Сравните пары Caster 4–6,5° и Camber −3…−5°. Меньше кастер и статический минус могут сделать пятно стабильнее на малом и среднем угле; результат зависит от выворота и остальной геометрии. В этом сравнении Mechanical trail сохраняется.','Сравнить Caster и Camber','caster'],
 ['03','Mechanical trail и Self-steering','Mechanical trail — продольное плечо между осью поворота на дороге и пятном контакта. Его можно увеличить смещением ступицы относительно оси, не увеличивая кастер. Так можно сохранить момент самоповорота и уменьшить изменение развала на вывороте.','На большом вывороте эффективное плечо меняется. Достаточный trail при δ = 0 не гарантирует одинаковый селфстиринг на всём диапазоне.','Опыт: Caster 4°, Camber −3°, Trail 55 мм','trail'],
 ['04','KPI и Camber gain','KPI / SAI — поперечный наклон оси поворота. При вывороте обычно добавляет положительный развал обоим колёсам и участвует в подъёме кузова. Меньший KPI уменьшает эту составляющую залома.','Сравните снижение KPI: 12° → 10° → 8° при том же вывороте. У МакФерсона изменение опоры стойки одновременно меняет несколько параметров; здесь кнопки меняют только KPI.','Сравнить KPI','kpi'],
 ['05','Scrub radius и Feedback','Это поперечное плечо, а не mechanical trail. Большой модуль усиливает реакцию руля на продольные силы, разницу торможения и удары. Смена знака меняет направление этой реакции.','Сильный толчок в руле не обязательно означает полезную обратную связь. На вывороте плечи перемешиваются из-за наклона оси поворота.','Опыт: Scrub radius +80 мм и толчок RF','scrub'],
 ['06','Roll center и баланс передка','Высокий передний RC уменьшает плечо крена, но увеличивает геометрическую долю переноса нагрузки. Меньше крена не означает автоматически больше переднего зацепа: нагруженная шина обычно не компенсирует потери разгруженной.','У МакФерсона занижение может заметно опустить RC. Коррекция шаровой меняет RC, но также требует проверки bump steer, хода и всей кинематики.','Сравнить Roll center: 160 мм','rc']
 ];
$('lessons').innerHTML=lessons.map(([index,title,p,small,action,key])=>`<article class="lesson"><div class="index">/ ${index}</div><h3>${title}</h3><p>${p}</p><p class="small">${small}</p>${key==='caster'?alignmentButtons():key==='kpi'?kpiButtons():`<button data-lesson="${key}">${action}</button>`}</article>`).join('');
document.querySelector('[data-lesson=ack]').insertAdjacentHTML('afterend','<button class="ack-guide-button" data-ack-guide>Почему меняется поведение машины</button>');
document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{free=false;scene='drift';const k=b.dataset.lesson;if(k==='ack')view='compare';if(k==='trail'){Object.assign(state,{caster:4,camber:-3,trail:55,kpi:8,steer:-28,beta:-32,yaw:18});lockTrail=true;view='suspension'}if(k==='scrub'){state.scrub=80;shockUntil=performance.now()+1000;view='top'}if(k==='rc'){state.rc=160;view='suspension'}sync();render();document.querySelector('.stage-panel').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})});
document.querySelectorAll('[data-kpi-preset]').forEach(b=>b.onclick=()=>{if(b.closest('.lesson')&&!['suspension','contact'].includes(view))view='suspension';setValue('kpi',+b.dataset.kpiPreset);if(b.closest('.lesson'))document.querySelector('.stage-panel').scrollIntoView({behavior:'smooth',block:'start'})});
document.querySelectorAll('[data-alignment-caster]').forEach(b=>b.onclick=()=>{free=false;steerVelocity=0;lockTrail=true;scene='custom';Object.assign(state,{caster:+b.dataset.alignmentCaster,camber:+b.dataset.alignmentCamber});if(!['suspension','contact'].includes(view))view='suspension';sync();render();document.querySelector('.stage-panel').scrollIntoView({behavior:'smooth',block:'start'})});
$('method').innerHTML=`<p><strong>Назначение.</strong> Интерактивная причинно-следственная модель передней оси МакФерсона. Это не валидированный симулятор конкретного автомобиля. Скорость, β и вращение кузова задаются независимо; траектория и полный баланс передних / задних шин не интегрируются. Положение машины интегрируется из заданных скорости, β и вращения кузова. Силы колёс показаны отдельно и не меняют заданное движение.</p><p><strong>Соглашения.</strong> x — вперёд, y — влево, z — вверх. Поворот и yaw влево положительны. β — угол скорости к продольной оси. Развал отрицателен, когда верх колеса наклонён внутрь. LF / RF — левое / правое переднее со стороны водителя. При контррулении «внутреннее по рулению» не равно «внутреннему по траектории».</p><p><strong>Ackermann offset в миллиметрах.</strong> 0 мм — условное положение точки тяги, при котором модель даёт параллельные базовые углы до добавления Bump steer. Шаг 1,5 мм; «+» наружу, «−» внутрь, симметрично на двух кулаках. После перестановки длина тяг считается отрегулированной для сохранения нулевого схождения. Используется идеализированная геометрия сходимости рулевых рычагов: <code>p = side · d / h</code>, <code>δᵢ = atan2(tan δ, 1 − wheelSide · p · tan δ)</code>. Здесь d — смещение в мм, h — продольное плечо рычага в мм; side = +1 для рычага перед осью и −1 за осью; wheelSide = +1 слева, −1 справа. Плечо по умолчанию 100 мм условное. Это не универсальный перевод миллиметров в углы: координаты рейки, длины тяг и полная рулевая трапеция не решаются. У реальной подвески даже «нулевая» вставка не обязана давать параллельность во всём диапазоне. Шаг регулировки основан на <a href="https://usa.wisefab.com/resources/how-to-use-wisefab-ackermann-washers" target="_blank" rel="noopener">описании регулировочных шайб Wisefab</a>; численная модель не является калибровкой их комплекта.</p><p><strong>Slip angle и шины.</strong> <code>Vᵢ = (u − r·yᵢ, v + r·a)</code>; <code>αᵢ = δᵢ − atan2(Vyᵢ,Vxᵢ)</code>. Боковая сила рассчитана условной насыщаемой кривой с чувствительностью к нагрузке и развалу. Пневматический trail убывает с уводом. Коэффициенты не взяты из измерений шины. Отдельная вкладка «Contact patch» рассчитывает оценку площади и нормального давления упругой опорной поверхности. Эта оценка не перекалибровывает условную кривую боковой силы.</p><p><strong>Caster, KPI, Mechanical trail.</strong> Плоскость жёсткого колеса вращается в 3D вокруг оси <code>k ∝ (−tan caster, −side·tan KPI, 1)</code>; угол вращения подбирается под заданный выворот в плане. Отсюда вычисляются развал, изменение высоты и плечи сил. Номинальный радиус колеса рассчитывается из ширины, профиля и посадочного диаметра; для 235/45 R17 это 321,65 мм. Динамический радиус качения отдельно не решается. Смещение ступицы = <code>R·tan(caster) − trail</code>. Без фиксации trail смена кастера сохраняет это смещение, пока не достигнут предел ползунка; с фиксацией подразумевается изменение конструкции кулака / положения ступицы.</p><p><strong>Body roll.</strong> Масса 1250 кг; 55% спереди; высота CG 520 мм; задний RC 80 мм; передняя жёсткость крена рассчитывается из пружин, Motion ratio и стабилизатора; задняя зафиксирована 65 000 Н·м/рад. Принято <code>aᵧ = u·r</code>, квазистатический крен по плечу до оси крена, геометрический + упругий перенос нагрузки. Условно 25% развала от крена компенсируется ходом подвески. Миграция RC, полная кинематика хода и неподрессоренные массы не решаются. Bump steer добавляется по отдельно заданной кривой. Схема рычагов иллюстрирует принцип; ползунки не являются чертежом совместимой сборки.</p><p><strong>Руль.</strong> Момент — сумма проекций <code>(плечо × сила) · k</code>, момента шины и вклада вертикальной нагрузки, приведённая к центральному δ. Подъём кузова от руления показан в моменте, но его перераспределение нагрузок по четырём углам не рассчитано. «Отпустить руль» интегрирует <code>I·δ̈ = M − c·δ̇</code> с условной инерцией 3,5 кг·м², демпфированием и упорами ±55°. Усилитель, трение рейки, передаточное отношение рулевого колеса, гироскопические эффекты и динамика водителя отсутствуют. Поэтому показанные Н·м не являются усилием на ободе руля.</p><p><strong>Contact patch: оценка, а не измерение.</strong> Размер шины сам по себе не задаёт реальную площадь. Здесь протектор — сплошная упругая поверхность без канавок: <code>q = K·max(0, z − x²/(2R) − y²/(2Rc) + t·y)</code>, где x вдоль качения, y наружу от машины, q — нормальное давление. Вдавливание z подбирается так, чтобы интеграл давления равнялся Fz каждого колеса. Поперечная выпуклость условно 2,5 мм до плеча; Rc = (W/2)²/5. При нулевом развале, податливости 1 и нагрузке 3372 Н жёсткость K калибруется по приближению A = Fz/P. В остальных режимах площадь получена интегрированием: равенство A = Fz/P не навязывается. Коэффициент податливости c меняет K в 1/√c раза и наклон поверхности t = tan(γ)/(1 + 2c); это учебные допущения, не свойства конкретной марки шины. При наклоне давление смещается к плечу, а при отрыве участка его давление равно нулю. Tire width 235 мм — номинальная ширина сечения: она условно принята за ширину опорной поверхности; реальный протектор обычно отличается. Профиль 45% даёт высоту боковины 105,75 мм, R17 — посадочный диаметр 431,8 мм. Профиль и диск меняют номинальный радиус, но не определяют реальную жёсткость боковины.</p><p>Цвет показывает <em>нормальное давление на дорогу</em>, а не давление воздуха. Нагрузка внутренней / наружной половины — доля интеграла давления по соответствующей половине протектора. Пунктир на графике — текущий центральный угол δ; при построении кривых движение кузова и нагрузки сохранены, меняется только руление. Кастер, KPI, развал и Аккерман меняют наклон каждого колеса; ролл-центр — крен и нагрузки. Trail и радиус обката в этой модели влияют на рулевой момент, но не задают пятно при удерживаемом угле. Температура, реальный каркас, ширина диска, рисунок протектора и сдвиг пятна от боковой силы не моделируются. Для точного расчёта нужны измерения конкретной шины. См. <a href="https://portal.fis.tum.de/de/publications/a-model-for-steady-state-tire-contact-pressure-distribution/" target="_blank" rel="noopener">исследование TUM: давление, нагрузка, развал и распределение контакта</a> и <a href="https://simulation.michelin.com/tametire" target="_blank" rel="noopener">Michelin: физические модели и параметры шины</a>. Эти источники подтверждают зависимости; формула выше — отдельная упрощённая модель лаборатории.</p><p><strong>Bump steer.</strong> Входные точки a = Toe change при +25 мм и b = Toe change при −25 мм задают кривую <code>τ(z) = (a−b)·z/50 + (a+b)·z²/1250</code>. τ = 0 при исходной высоте; положительный τ означает toe-in. Кривые LF/RF одинаковы, а изменение угла руления зеркальное: <code>δᵢ = δAckermann − side·τ</code>. При включённой связи с креном <code>zᵢ = Wheel inputᵢ − side·T/2·tan(φ)</code>, с ограничением ±75 мм. Кривая — ввод измерений / учебный пример, не решение 3D-точек МакФерсона. Вне ±25 мм применяется квадратичная экстраполяция. Зависимость кривой от выворота, ходовой развал и кастер, податливость втулок и геометрия рейки отдельно не рассчитаны. Ручной ход меняет кинематическое подруливание, но не задаёт ударную силу, нагрузку на пружину или движение кузова. Toe в мм = диаметр шины · sin(τ), на одно колесо. Принципы: <a href="https://race.software/academy/suspension-designer-library/bump-steer-and-roll-steer/" target="_blank" rel="noopener">RACE: Bump steer / Roll steer</a>; <a href="https://race.software/tuning-bump-steer-linearity/" target="_blank" rel="noopener">RACE: положение и длина рулевой тяги влияют на форму кривой</a>.</p><p><strong>Front suspension stiffness.</strong> Spring rate задана для одной пружины в kgf/mm (1 kgf/mm = 9,80665 N/mm). <code>Wheel rate = Spring rate · MR²</code>, MR = ход пружины / ход колеса. В MR уже включён эффект наклона установки, повторный cos не применяется. <code>Kφ_front = Wheel rate · T²/2 + Kφ_ARB</code> с переводом Wheel rate в N/m; общая жёсткость = передняя + 65 000 Н·м/рад задней оси. Крен <code>φ = m·aᵧ·(hCG−hRA)/Kφ_total</code>; передний упругий перенос нагрузки <code>ΔFz = Kφ_front·φ/T</code>. Поэтому увеличение передней жёсткости уменьшает крен, но увеличивает её долю упругого переноса нагрузки. Исходные 8 kgf/mm, MR 0,95, передний ARB 15 kN·m/rad и задние 65 kN·m/rad — условные параметры. Сохранение исходной высоты при смене жёсткости подразумевает перенастройку преднатяга. Демпферы подвески, частотная реакция на неровности и отбойники не моделируются. Соглашение MR: <a href="https://race.software/academy/design-with-race-guide/" target="_blank" rel="noopener">RACE: spring / damper motion ratio и параметры пружин</a>.</p><p><strong>Источники принципов.</strong> <a href="https://usa.wisefab.com/wf550-ford-mustang-s550-front-drift-angle-lock-kit" target="_blank" rel="noopener">Wisefab: геометрия дрифта, trail и самоповорот</a>; <a href="https://optimumg.com/optimal-thinking-part-2/" target="_blank" rel="noopener">OptimumG: caster, KPI и подъём кузова при рулении</a>; <a href="https://optimumg.com/vehicle-setup-and-kinematics-qa-series/" target="_blank" rel="noopener">OptimumG: кинематика и перенос нагрузки</a>; <a href="https://www.racingaspirations.com/roll-center-analysis/" target="_blank" rel="noopener">Racing Aspirations: построение центра крена</a>. Условные численные коэффициенты и эксперименты — допущения этой модели, не рекомендованные настройки производителей.</p>`;
function tick(time){const dt=lastTime?Math.min((time-lastTime)/1000,.04):.016;lastTime=time;let needs=false;if(running){if(scene==='transition'){phase+=dt*.7;state.beta=-32*Math.cos(phase);state.yaw=18*Math.cos(phase);if(!free)state.steer=state.beta*.875;needs=true}if(free){for(let i=0;i<4;i++){const rr=M.calculate(state,time<shockUntil?1000:0),h=dt/4;steerVelocity+=(rr.torque-state.damping*steerVelocity)/3.5*h;steerVelocity=M.clamp(steerVelocity,-5,5);state.steer+=steerVelocity*h*M.deg;if(Math.abs(state.steer)>55){state.steer=M.clamp(state.steer,-55,55);steerVelocity=0}}needs=true}if(time<shockUntil+100)needs=true}if(needs&&(!['contact','bump'].includes(view)||time-lastContactPaint>100)){sync();render();lastContactPaint=time}requestAnimationFrame(tick)}
sync();render();requestAnimationFrame(tick);
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'configure_drift_geometry',description:'Change the same suspension and drift parameters as the visible controls; returns current wheel measurements.',inputSchema:{type:'object',properties:{...Object.fromEntries(definitions.map(d=>[d[0],{type:'number',minimum:d[2],maximum:d[3],...(d[0]==='ack'?{multipleOf:1.5,description:'Tie-rod outer pickup offset in millimetres: positive outward, negative inward; zero gives parallel steering.'}:{})}])),bumpFromRoll:{type:'number',enum:[0,1],description:'Include quasi-static body-roll wheel travel in bump steer.'},rackSide:{type:'number',enum:[-1,1],description:'Steering arm in front of axle: +1; behind axle: -1.'}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Expected parameter object');for(const [k,v]of Object.entries(input)){if(k==='bumpFromRoll'){if(![0,1].includes(v))throw Error('Invalid roll link');continue}if(k==='rackSide'){if(![-1,1].includes(v))throw Error('Invalid steering arm side');continue}const d=definitions.find(d=>d[0]===k);if(!d||typeof v!=='number'||!Number.isFinite(v)||v<d[2]||v>d[3]||(k==='ack'&&Math.abs(v/1.5-Math.round(v/1.5))>1e-9))throw Error('Invalid parameter: '+k)}free=false;scene='custom';for(const [k,v]of Object.entries(input))setValue(k,v);render();return {parameters:{...state},wheels:result.wheels.map(w=>({wheel:w.name,steer:w.delta,slip:w.alpha,camber:w.camber,loadN:w.Fz,wheelTravel:w.travel,toeChange:w.toeChange,bumpDelta:w.bumpDelta,contact:M.contactPatch(state,w)})),torqueNm:result.torque,suspensionRates:result.rates}}}, {signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort())}catch{}}
// Prescribed body motion; forces are measured but do not integrate the vehicle trajectory.
let pose={x:0,y:0,heading:-state.beta*M.rad,history:[],radius:state.speed/3.6/(state.yaw*M.rad||.001)},courseFrame=0;
function resetPose(){pose={x:0,y:0,heading:-state.beta*M.rad,history:[],radius:Math.abs(state.yaw)>.3?state.speed/3.6/(state.yaw*M.rad):0}}
function movePose(dt){const v=state.speed/3.6,w=state.yaw*M.rad,h=pose.heading,b=state.beta*M.rad;pose.heading+=w*dt;if(Math.abs(w)>.0001){pose.x+=v/w*(Math.sin(pose.heading+b)-Math.sin(h+b));pose.y+=v/w*(-Math.cos(pose.heading+b)+Math.cos(h+b))}else{pose.x+=v*dt*Math.cos(h+b);pose.y+=v*dt*Math.sin(h+b)}pose.history.push([pose.x,pose.y]);if(pose.history.length>550)pose.history.shift()}
function courseView(r){const lead=Math.abs(state.beta)<.5?null:(state.beta<0?1:0),trailing=lead===null?null:1-lead,R=pose.radius,scale=R?128/Math.abs(R):3,sc=20;
 let ox=0,oy=R,px=x=>267+(x-ox)*scale,py=y=>245-(y-oy)*scale;
 if(scene==='transition'||!R){ox=pose.x;oy=pose.y;px=x=>267+(x-ox)*2.3;py=y=>245-(y-oy)*2.3}
 let x=px(pose.x),y=py(pose.y),heading=pose.heading*M.deg;
 if(x<65||x>470||y<85||y>413){ox=pose.x;oy=pose.y;px=x=>267+(x-ox)*scale;py=y=>245-(y-oy)*scale;x=267;y=245}
 let h=svgStart('Автомобиль движется в заносе по заданному повороту. Показаны направления ведущего и ведомого колёс относительно касательной.');
 h+=`<defs><clipPath id="road-clip"><rect x="12" y="75" width="495" height="330" rx="8"/></clipPath></defs><g clip-path="url(#road-clip)">`;
 if(R&&scene!=='transition'){h+=`<circle cx="${px(0)}" cy="${py(R)}" r="${Math.abs(R)*scale}" fill="none" stroke="#26323b" stroke-width="66"/><circle cx="${px(0)}" cy="${py(R)}" r="${Math.abs(R)*scale}" fill="none" stroke="#718191" stroke-dasharray="10 12"/><circle cx="${px(0)}" cy="${py(R)}" r="${Math.abs(R)*scale-35}" fill="none" stroke="#384b58"/><circle cx="${px(0)}" cy="${py(R)}" r="${Math.abs(R)*scale+35}" fill="none" stroke="#384b58"/>`}
 if(pose.history.length>1)h+=`<path d="${pose.history.map((p,i)=>(i?'L':'M')+px(p[0]).toFixed(1)+' '+py(p[1]).toFixed(1)).join(' ')}" stroke="#65d8ef" opacity=".45" stroke-width="3" fill="none"/>`;
 const vhead=pose.heading+state.beta*M.rad;h+=arrow(x-60*Math.cos(vhead),y+60*Math.sin(vhead),150*Math.cos(vhead),-150*Math.sin(vhead),colors.cyan,2.5);
 h+=`<g transform="translate(${x},${y}) rotate(${90-heading})"><path d="M-18 -49Q0 -60 18 -49L21 39Q0 51 -21 39Z" fill="#314554" stroke="#a6b9c5" stroke-width="1.7"/><path d="M-13 -26H13L16 -9H-16Z" fill="#0e1b24" stroke="#587487"/><path d="M0 -70V58" stroke="#c4d3dd" stroke-dasharray="5 5" opacity=".7"/>`;
 const fy=-state.wheelbase/1000*.45*sc,ry=state.wheelbase/1000*.55*sc;
 for(const [i,w] of r.wheels.entries()){const wx=-w.side*state.track/1000/2*sc;const d=w.delta*M.rad;h+=`<path d="M${wx} ${fy}l${-Math.sin(d)*76} ${-Math.cos(d)*76}" stroke="${i===lead?'#c6f36b':'#d5afff'}" stroke-width="2" stroke-dasharray="4 3"/><g transform="translate(${wx},${fy}) rotate(${-w.delta})"><rect x="-5" y="-11" width="10" height="22" rx="2" fill="#1c2b1a" stroke="${i===lead?'#c6f36b':'#d5afff'}" stroke-width="2"/></g><text x="${wx+(w.side===1?-10:10)}" y="${fy+16}" text-anchor="middle" fill="${i===lead?'#c6f36b':'#d5afff'}" font-size="9">${w.name}</text><rect x="${wx-5}" y="${ry-10}" width="10" height="20" rx="2" fill="#142029" stroke="#879eac"/>`}
 h+=`</g></g><text x="26" y="33" fill="#c6f36b" font-size="14">${state.yaw>0?'ЛЕВЫЙ ПОВОРОТ':state.yaw<0?'ПРАВЫЙ ПОВОРОТ':'ПРЯМАЯ'} · β ${sgn(state.beta)}°</text><text x="26" y="57" fill="#99a7b2" font-size="12">Yaw rate r ${sgn(state.yaw)}°/с · ${R?'Turn radius '+fmt(Math.abs(R),0)+' м':'прямая'}</text>`;
 h+=`<text x="26" y="435" fill="#65d8ef" font-size="13">Голубая стрелка — касательная / скорость</text><text x="26" y="456" fill="#99a7b2" font-size="12">Положение кузова задано β; силы не меняют эту дугу.</text><path d="M513 78V458" stroke="#34454f"/><text x="537" y="34" fill="#edf2f4" font-size="16">Передняя ось крупно</text><text x="537" y="58" fill="#99a7b2" font-size="12">Угол к локальной траектории = увод α</text>`;
 for(const [i,w] of r.wheels.entries()){let xx=583+i*145,yy=175,d=w.delta*M.rad,b=w.direction*M.rad,c=i===lead?'#c6f36b':'#d5afff';h+=arrow(xx,yy,-Math.sin(b)*74,-Math.cos(b)*74,colors.cyan,1.7);h+=`<path d="M${xx+Math.sin(d)*52} ${yy+Math.cos(d)*52}L${xx-Math.sin(d)*72} ${yy-Math.cos(d)*72}" stroke="${c}" stroke-width="1.5" stroke-dasharray="4 4"/><g transform="translate(${xx},${yy}) rotate(${-w.delta})"><rect x="-10" y="-25" width="20" height="50" rx="4" fill="#20332b" stroke="${c}" stroke-width="2"/></g>`;h+=arrow(xx,yy,-Math.cos(d)*w.Fy/100,Math.sin(d)*w.Fy/100,colors.orange,2);h+=`<text x="${xx}" y="251" text-anchor="middle" fill="${c}" font-size="14">${w.name} · ${lead===null?'роль не задана':i===lead?'Leading':'Trailing'}</text><text x="${xx}" y="276" text-anchor="middle" fill="#edf2f4" font-size="16">δ ${sgn(w.delta)}°</text><text x="${xx}" y="299" text-anchor="middle" fill="#65d8ef" font-size="13">α ${sgn(w.alpha)}°</text>`}
 const w=r.wheels[trailing??0],yawEffect=Math.abs(w.yawMoment)<25?'Малый момент этой силы':w.yawMoment>0?'Момент этой силы: влево':'Момент этой силы: вправо';
 h+=`<text x="537" y="336" fill="#d5afff" font-size="14">Trailing ${lead===null?'не определено':w.name} · сила на передок</text><text x="537" y="361" fill="#ffa66b" font-size="14">${yawEffect}</text><text x="537" y="385" fill="#99a7b2" font-size="13">Mᶻ ${sgn(w.yawMoment,0)} Н·м · ${w.yawMoment>0?'↶ влево':'вправо ↷'}</text><text x="537" y="413" fill="#edf2f4" font-size="11">Body-longitudinal force: ${sgn(w.bodyFx,0)} Н</text><text x="537" y="437" fill="#99a7b2" font-size="11">Path-longitudinal force: ${sgn(w.pathLong,0)} Н</text><text x="537" y="460" fill="#99a7b2" font-size="11">Это вклад одной шины, не прогноз Oversteer</text></svg>`;
 const divider='<path d="M513 78V458" stroke="#34454f"/>';
 h=h.replace('viewBox="0 0 820 480"','viewBox="0 0 513 480"').replace(divider,'</svg><svg viewBox="513 0 307 480" role="img" aria-label="Ведущее и ведомое колёса относительно траектории">');
 return '<div class="course-grid">'+h+'</div>';
}
// Pressure and contact area are an uncalibrated vertical tyre model, separate from Fy.
const contactCurveCache=new Map();
function contactCurve(){const key=JSON.stringify(Object.fromEntries(Object.entries(state).filter(([k])=>k!=='steer')));if(contactCurveCache.has(key))return contactCurveCache.get(key);const curve=[];for(let d=-55;d<=55;d+=5){const s={...state,steer:d};curve.push({d,values:M.calculate(s).wheels.map(w=>M.contactPatch(s,w).areaCm2)})}if(contactCurveCache.size>12)contactCurveCache.clear();contactCurveCache.set(key,curve);return curve}
function patchColor(t){const stops=[[19,39,55],[38,119,158],[96,211,199],[198,243,107],[255,172,85],[255,94,94]],v=M.clamp(t,0,1)*(stops.length-1),i=Math.min(stops.length-2,Math.floor(v)),f=v-i;return stops[i].map((a,j)=>Math.round(a*(1-f)+stops[i+1][j]*f))}
function drawPatch(canvas,p,side,peak){const ctx=canvas.getContext('2d'),W=360,H=220,scale=W/(state.tyreWidth+80),cx=W/2,cy=H/2;canvas.width=W;canvas.height=H;const img=ctx.createImageData(W,H);for(let v=0;v<H;v++)for(let u=0;u<W;u++){const x=(cy-v)/scale,y=-side*(u-cx)/scale,q=M.contactPressure(p,x,y)*10,k=(v*W+u)*4;if(q>.002){const c=patchColor(q/peak);img.data[k]=c[0];img.data[k+1]=c[1];img.data[k+2]=c[2];img.data[k+3]=255}}ctx.putImageData(img,0,0);ctx.strokeStyle='#617685';ctx.lineWidth=1;ctx.setLineDash([4,5]);ctx.strokeRect(cx-state.tyreWidth/2*scale,12,state.tyreWidth*scale,H-24);ctx.strokeStyle='#bdd0d766';ctx.beginPath();ctx.moveTo(cx,12);ctx.lineTo(cx,H-12);ctx.stroke();ctx.setLineDash([]);if(p.area){const px=cx-side*p.centroid*scale;ctx.strokeStyle='#ffffff';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(px-5,cy);ctx.lineTo(px+5,cy);ctx.moveTo(px,cy-5);ctx.lineTo(px,cy+5);ctx.stroke()}else{ctx.fillStyle='#99a7b2';ctx.font='15px Segoe UI';ctx.textAlign='center';ctx.fillText('Колесо разгружено',cx,cy)}ctx.strokeStyle='#a2b2bd';ctx.beginPath();const y=H-5;ctx.moveTo(15,y);ctx.lineTo(15+50*scale,y);ctx.stroke();ctx.fillStyle='#99a7b2';ctx.font='11px Segoe UI';ctx.fillText('50 мм',15,y-5)}
function patchPlot(curve,patches){const max=Math.ceil(Math.max(...curve.flatMap(p=>p.values),...patches.map(p=>p.areaCm2),1)/50)*50,X=d=>48+(d+55)/110*612,Y=a=>173-a/max*126,cc=['#d5afff','#c6f36b'];let h='<svg viewBox="0 0 700 226" role="img" aria-label="График площади пятна контакта левого и правого передних колёс от поворота руля"><text x="48" y="24" fill="#99a7b2" font-size="12">Contact area, см²</text>';for(let j=0;j<=4;j++){const a=max*j/4,y=Y(a);h+=`<path d="M48 ${y}H660" stroke="#293944"/><text x="40" y="${y+4}" text-anchor="end" fill="#99a7b2" font-size="11">${fmt(a,0)}</text>`}for(const d of [-55,-30,0,30,55])h+=`<path d="M${X(d)} 47V177" stroke="#263641"/><text x="${X(d)}" y="195" text-anchor="middle" fill="#99a7b2" font-size="12">${sgn(d,0)}°</text>`;for(let i=0;i<2;i++){h+=`<path d="${curve.map((p,j)=>(j?'L':'M')+X(p.d).toFixed(2)+' '+Y(p.values[i]).toFixed(2)).join(' ')}" fill="none" stroke="${cc[i]}" stroke-width="2.5" ${i===0?'stroke-dasharray="6 3"':''}/>`}h+=`<path d="M${X(state.steer)} 41V180" stroke="#dce9f3" stroke-dasharray="3 4"/>`;for(let i=0;i<2;i++)h+=`<circle cx="${X(state.steer)}" cy="${Y(patches[i].areaCm2)}" r="4.5" fill="${cc[i]}" stroke="#101a21" stroke-width="1.5"/>`;return h+'<text x="354" y="220" text-anchor="middle" fill="#99a7b2" font-size="12">Steering angle δ · те же нагрузки и состояние кузова</text></svg>'}
function renderContact(r){const patches=r.wheels.map(w=>M.contactPatch(state,w)),straight=M.calculate({...state,steer:0}).wheels.map(w=>M.contactPatch(state,w)),peak=Math.max(1,Math.ceil(Math.max(...patches.map(p=>p.peakBar))*2)/2),size=fmt(state.tyreWidth,0)+'/'+fmt(state.tyreAspect,0)+' R'+fmt(state.rimDiameter,0),curve=contactCurve();
 $('view-caption').textContent='Contact area / pressure · оценка';
 $('stage').innerHTML=`<div class="contact-wrap"><div class="contact-heading"><div><h2>${size}</h2><p>Sidewall height ${fmt(state.tyreWidth*state.tyreAspect/100,2)} мм · Tire diameter ${fmt(M.tyreRadius(state)*2)} мм</p></div><span class="estimate-badge">Оценочная модель</span></div><div class="patch-grid">${r.wheels.map((w,i)=>{const p=patches[i],ref=straight[i],change=ref.area?100*(p.area/ref.area-1):null,color=i?'#c6f36b':'#d5afff';return `<section class="patch-card" style="--wheel-color:${color}"><div class="patch-card-head"><h3>${w.name} <span>${i?'Правое':'Левое'} переднее</span></h3><b>${fmt(p.areaCm2,0)} <small>см²</small></b></div><p class="patch-values">Steering angle <strong>${sgn(w.delta)}°</strong> · Camber <strong>${sgn(w.camber)}°</strong><br>Wheel load ${fmt(w.Fz/1000,2)} кН · ${fmt(w.Fz/9.81,0)} кгс</p><div class="patch-orientation"><span>${i?'Внутри':'Снаружи'}</span><span>↑ Вперёд по колесу</span><span>${i?'Снаружи':'Внутри'}</span></div><canvas id="footprint-${w.name}" class="footprint" role="img" aria-label="Пятно контакта ${w.name}: ${fmt(p.areaCm2,0)} квадратных сантиметров; на внутреннюю половину приходится ${fmt(p.innerShare*100,1)} процентов нагрузки"></canvas><div class="patch-stats"><div><span>Contact width × length</span><b>${fmt(p.width,0)} × ${fmt(p.length,0)} мм</b></div><div><span>Pressure · mean / peak</span><b>${fmt(p.meanBar)} / ${fmt(p.peakBar)} бар</b></div></div><div class="patch-load-label"><span>Inner load <b>${p.area?fmt(p.innerShare*100,1)+'%':'—'}</b></span><span>Outer load <b>${p.area?fmt(p.outerShare*100,1)+'%':'—'}</b></span></div><div class="patch-load-bar"><i style="width:${p.innerShare*100}%"></i></div><p class="patch-reference">${change!==null?`${sgn(change,0)}% площади к прямым колёсам при той же нагрузке`:'Нет контакта с дорогой'}</p></section>`}).join('')}</div><div class="pressure-key"><span>Contact pressure</span><div><i></i><span><b>0</b><b>${fmt(peak)} бар</b></span></div><small>Одна шкала для LF и RF.<br>Белый крест — центр давления.</small></div><div class="contact-chart"><div class="chart-heading"><h3>Contact area vs. Steering angle</h3><span><i class="lf-dot"></i> LF <i class="rf-dot"></i> RF</span></div>${patchPlot(curve,patches)}</div><p class="patch-explainer">Вид на дорогу в координатах каждой шины; масштаб у колёс одинаковый. Цвет — нормальное давление, без сдвига протектора от боковой силы. Площадь сама по себе не равна зацепу.</p></div>`;
 for(let i=0;i<2;i++)drawPatch($('footprint-'+r.wheels[i].name),patches[i],r.wheels[i].side,peak);
 $('insight').innerHTML=`<strong>Меняйте Steering angle над картой.</strong> Кастер и KPI меняют развал на вывороте, Аккерман — угол каждого колеса. Крен и перенос нагрузки делают пятна разными даже при одинаковом статическом развале. Давление ${fmt(state.tyrePressure)} бар и податливость ${fmt(state.tyreCompliance)}× задают деформацию в этой оценке. <span class="muted">Размер ${size} задан; конструкция конкретной шины не измерена. Значения в см² — ориентир для сравнения настроек.</span>${r.lift?'<br><span class="warning">Одно колесо разгружено: модель крена за пределами применимости.</span>':''}${r.overDemand?'<br><span class="warning">Заданное боковое ускорение выше μg; режим может быть недостижим.</span>':''}`;
}

function renderSelfSteer(r){const before=releasedFrom??state.steer;$('self-steer-status').classList.toggle('is-free',free);$('self-steer-status').innerHTML=free?`<div><h3>Self-steering · ${running?'руль отпущен':'пауза'}</h3><p>Steering angle: <b>${sgn(before)}° → ${sgn(state.steer)}°</b> · изменение ${sgn(state.steer-before)}°</p><p>Steering torque: <b>${sgn(r.torque,1)} Н·м</b> · ${Math.abs(r.torque)<1.5?'момент почти уравновешен':r.torque>0?'поворачивает колёса влево':'поворачивает колёса вправо'}</p></div><p class="control-hint">${running?'Момент от шин, trail и наклона оси сам меняет выворот.':'Расчёт остановлен кнопкой «Пауза».'} В заносе равновесный угол может быть далеко от нуля. «Удерживать руль» фиксирует текущий угол; траектория кузова остаётся заданной.</p>`:`<div><h3>Self-steering · руль удерживается</h3><p>Steering angle <b>${sgn(state.steer)}°</b> задаётся ползунком.</p></div><p class="control-hint">«Отпустить руль» разрешает колёсам самим повернуться под действием рулевого момента. Покажем начальный и текущий угол. Если руль уже близок к равновесию, изменение будет небольшим.</p>`}
function bumpControl(key){const d=definitions.find(x=>x[0]===key);return `<div class="control"><div class="control-top"><label for="bump-ui-${key}">${d[1]}</label><span><input id="bump-ui-${key}-number" aria-label="${d[1]} на схеме: значение" class="number-entry" type="number" min="${d[2]}" max="${d[3]}" step="${d[4]}" value="${state[key]}"> <span class="unit">${d[5]}</span></span></div><input id="bump-ui-${key}" type="range" min="${d[2]}" max="${d[3]}" step="${d[4]}" value="${state[key]}"><div class="endpoints"><span>${d[2]}</span><span>${d[3]}</span></div></div>`}
function bumpPlot(r){const samples=[];for(let z=-75;z<=75;z+=2.5)samples.push([z,M.bumpToeAt(state,z)]);const limit=Math.max(.15,Math.ceil(Math.max(...samples.map(p=>Math.abs(p[1])))*20)/20),X=z=>54+(z+75)/150*594,Y=t=>145-t/limit*95;let h='<svg viewBox="0 0 700 286" role="img" aria-label="Bump steer: изменение схождения от хода подвески"><text x="54" y="22" fill="#c6f36b" font-size="14">Toe change · + toe-in / − toe-out</text>';for(let j=-2;j<=2;j++){const v=limit*j/2;h+=`<path d="M54 ${Y(v)}H648" stroke="${j?'#2a3c48':'#6e8391'}"/><text x="46" y="${Y(v)+4}" text-anchor="end" fill="#99a7b2" font-size="12">${sgn(v,2)}°</text>`}for(let z=-75;z<=75;z+=25)h+=`<path d="M${X(z)} 45V240" stroke="#2a3c48"/><text x="${X(z)}" y="257" text-anchor="middle" fill="#99a7b2" font-size="12">${sgn(z,0)}</text>`;h+=`<path d="${samples.map((p,i)=>(i?'L':'M')+X(p[0]).toFixed(2)+' '+Y(p[1]).toFixed(2)).join(' ')}" fill="none" stroke="#65d8ef" stroke-width="2.5"/>`;for(const z of [-25,0,25])h+=`<circle cx="${X(z)}" cy="${Y(M.bumpToeAt(state,z))}" r="4" fill="#0e1921" stroke="#65d8ef" stroke-width="2"/>`;for(const [i,w]of r.wheels.entries()){const c=i?'#c6f36b':'#d5afff';h+=`<path d="M${X(w.travel)} 45V240" stroke="${c}" stroke-dasharray="4 5" opacity=".5"/><circle cx="${X(w.travel)}" cy="${Y(w.toeChange)}" r="${i?4:7}" fill="${i?c:'#101921'}" stroke="${c}" stroke-width="2"/><text x="${i?628:555}" y="38" fill="${c}" font-size="12">${w.name}</text>`}return h+'<text x="351" y="279" text-anchor="middle" fill="#99a7b2" font-size="12">Wheel travel, мм · отбой ← 0 → сжатие</text></svg>'}
function bumpMotion(r){let h='<svg viewBox="0 0 450 310" role="img" aria-label="Ход передних колёс и сжатие пружин: схема"><rect x="70" y="30" width="310" height="38" rx="7" fill="#22313b" stroke="#6c8190"/><text x="225" y="55" fill="#b8c9d5" font-size="13" text-anchor="middle">MacPherson · ход относительно кузова</text><path d="M30 218H420" stroke="#4c626f" stroke-dasharray="5 5"/>';for(const[i,w]of r.wheels.entries()){const x=104+i*242,y=188-w.travel*.7,c=i?'#c6f36b':'#d5afff',top=82,bottom=y-35;let coil=`M${x} ${top}`;for(let j=1;j<=10;j++)coil+=`L${x+(j%2?10:-10)} ${top+(bottom-top)*j/11}`;coil+=`L${x} ${bottom}`;h+=`<path d="M${x} 68V${y}" stroke="#6e8390" stroke-width="5"/><path d="${coil}" stroke="${c}" stroke-width="3" fill="none"/><path d="M${225+(i?38:-38)} 155L${x} ${y+8}" stroke="#8ca4b5" stroke-width="4"/><rect x="${x-14}" y="158" width="28" height="60" rx="4" fill="none" stroke="#506270" stroke-dasharray="4 4"/><g transform="translate(${x},${y}) rotate(${-w.side*w.camber})"><rect x="-16" y="-31" width="32" height="62" rx="5" fill="#223522" stroke="${c}" stroke-width="2"/></g><text x="${x}" y="281" text-anchor="middle" fill="${c}" font-size="15">${w.name} ${sgn(w.travel)} мм</text>`}return h+'<text x="225" y="303" text-anchor="middle" fill="#99a7b2" font-size="11">Пунктир — исходная высота. Рычаги показаны условно.</text></svg>'}
function renderBump(r){const keys=['wheelTravelLF','wheelTravelRF','bumpToe','reboundToe','springRate','motionRatio','frontBarRate'];if(!$('bump-live')){
 $('stage').innerHTML=`<div class="bump-wrap"><div class="contact-heading"><div><h2>Bump steer / Front stiffness</h2><p>Ход подвески меняет схождение при том же положении руля.</p></div></div><div id="bump-live" class="bump-live"></div><div class="bump-grid"><section class="bump-box"><h3>Wheel travel</h3><div id="bump-motion"></div>${bumpControl('wheelTravelLF')}${bumpControl('wheelTravelRF')}<label class="link-option"><input id="bump-ui-roll" type="checkbox"> Добавлять ход от Body roll</label><p class="control-hint">Wheel input — добавка вручную. Total travel включает её и ход от крена. «+» — сжатие, «−» — отбой.</p><div class="bump-presets"><button data-travel-test="heave">Оба +25 мм</button><button data-travel-test="roll">LF −25 / RF +25</button><button data-travel-test="body">От Body roll</button></div></section><section class="bump-box"><h3>Toe change vs. Wheel travel</h3><div id="bump-plot"></div>${bumpControl('bumpToe')}${bumpControl('reboundToe')}<p class="control-hint">Задайте изменение схождения при +25 и −25 мм хода. Через эти точки и ноль проходит расчётная кривая. Нулевая кривая — исходное допущение; реальные значения нужно измерить.</p><p class="bump-small-title">Учебные кривые</p><div class="bump-presets"><button data-bump-example="out">Toe-out in bump</button><button data-bump-example="zero">Zero</button><button data-bump-example="in">Toe-in in bump</button></div><p class="control-hint">Примеры ±0,10° при 25 мм. Применённая кривая одинакова для LF и RF; знак изменения угла руления зеркальный.</p></section></div><section class="bump-box stiffness-box"><h3>Front suspension stiffness</h3><div class="stiffness-controls">${['springRate','motionRatio','frontBarRate'].map(bumpControl).join('')}</div><div id="stiffness-live" class="stiffness-live"></div><p class="control-hint">Более жёсткий перед уменьшает крен и ход от него, но увеличивает переднюю долю упругого переноса нагрузки. При заданном вручную ходе сама кривая Bump steer не меняется от Spring rate. Motion ratio = ход пружины / ход колеса; угол установки уже учтён в нём.</p></section><p id="bump-notes" class="patch-explainer"></p></div>`;
 for(const key of keys)for(const suffix of ['','-number']){const el=$('bump-ui-'+key+suffix);el.oninput=e=>{if(e.target.value!=='')setValue(key,+e.target.value)};if(suffix)el.onchange=()=>{el.value=state[key]}}
 $('bump-ui-roll').onchange=e=>setValue('bumpFromRoll',e.target.checked?1:0);
 document.querySelectorAll('[data-bump-example]').forEach(b=>b.onclick=()=>{const a=b.dataset.bumpExample==='out'?-.1:b.dataset.bumpExample==='in'?.1:0;Object.assign(state,{bumpToe:a,reboundToe:-a});sync();render()});
 document.querySelectorAll('[data-travel-test]').forEach(b=>b.onclick=()=>{const type=b.dataset.travelTest;Object.assign(state,type==='body'?{bumpFromRoll:1,wheelTravelLF:0,wheelTravelRF:0}:{bumpFromRoll:0,wheelTravelLF:type==='heave'?25:-25,wheelTravelRF:25});sync();render()});
 }
 for(const key of keys)for(const suffix of ['','-number']){const el=$('bump-ui-'+key+suffix);if(document.activeElement!==el||!suffix)el.value=state[key]}
 $('bump-ui-roll').checked=!!state.bumpFromRoll;
 document.querySelectorAll('[data-bump-example]').forEach(b=>{const a=b.dataset.bumpExample==='out'?-.1:b.dataset.bumpExample==='in'?.1:0;b.classList.toggle('active',Math.abs(state.bumpToe-a)<1e-8&&Math.abs(state.reboundToe+a)<1e-8)});
 $('bump-live').innerHTML=r.wheels.map((w,i)=>`<div style="--wheel-color:${i?'#c6f36b':'#d5afff'}"><h3>${w.name} · Total travel <b>${sgn(w.travel)} мм</b></h3><p>Toe change <strong>${sgn(w.toeChange,3)}°</strong> / ${sgn(w.toeMm,2)} мм</p><p>Steering angle ${sgn(w.baseDelta,2)}° → <strong>${sgn(w.delta,2)}°</strong></p><small>Body roll ${sgn(w.rollTravel)} мм + Wheel input ${sgn(w.manualTravel)} мм</small></div>`).join('');
 $('bump-motion').innerHTML=bumpMotion(r);$('bump-plot').innerHTML=bumpPlot(r);
 $('stiffness-live').innerHTML=metric('Wheel rate',fmt(r.rates.wheelNmm)+' N/mm','Одна передняя сторона, без стабилизатора')+metric('Front roll stiffness',fmt(r.rates.frontRoll/1000)+' kN·m/rad',`Springs ${fmt(r.rates.springRoll/1000)} + ARB ${fmt(r.rates.barRoll/1000)}`)+metric('Body roll',sgn(r.roll,2)+'°',`Ход от крена LF/RF: ${sgn(-state.track/2*Math.tan(r.roll*M.rad))} / ${sgn(state.track/2*Math.tan(r.roll*M.rad))} мм`)+metric('Front elastic transfer',fmt(Math.abs(r.elastic)/1000,2)+' кН',`Передняя доля roll stiffness: ${fmt(r.rates.frontFraction*100,0)}%`);
 $('bump-notes').innerHTML=`Toe-in положителен на обоих колёсах; для LF он уменьшает Steering angle, для RF увеличивает. Миллиметры Toe change приведены к диаметру шины ${fmt(M.tyreRadius(state)*2)} мм, на одно колесо. Кривая задана напрямую, не рассчитана из точек крепления рейки и рычагов; за ±25 мм это экстраполяция. Ручной ход не добавляет вертикальную силу и не рассчитывает отдельный Bump camber. Rear roll stiffness фиксирована: 65 kN·m/rad.${r.wheels.some(w=>w.travelLimited)?'<br><span class="warning">Суммарный ход вышел за диапазон: для кривой ограничен ±75 мм. Работа отбойников не рассчитывается.</span>':''}`;
 $('view-caption').textContent='Bump / rebound · toe-in / toe-out';
 $('insight').innerHTML=`<strong>Spring rate → Body roll → Wheel travel → Bump steer.</strong> При заданном боковом ускорении жёсткость определяет крен; ход от крена берёт текущую точку на кривой схождения. Итоговый угол колеса используется в схемах, силах и Contact patch. ${state.bumpToe===0&&state.reboundToe===0?'Сейчас кривая нулевая: включите Toe-out in bump или введите свои измерения, чтобы увидеть подруливание.':'Сравните Toe change LF/RF при сжатии обоих колёс и при противоположном ходе.'} <span class="muted">Кривая от неподвижного руля переносится на выворот как приближение; для точного дрифт-комплекта нужны измерения на разных углах.</span>`;
}

const baseRender=render;
render=function(){$('patch-adjust').hidden=view!=='contact';document.querySelector('.legend').hidden=['contact','bump'].includes(view);$('stage').className='stage '+view+'-mode';baseRender();if(view==='contact'){renderContact(result)}if(view==='course'){$('stage').innerHTML=courseView(result);const li=Math.abs(state.beta)<.5?null:state.beta<0?1:0;if(li!==null){const w=result.wheels[1-li];$('insight').innerHTML=`<strong>Leading ${result.wheels[li].name} · Trailing ${w.name}.</strong> Голубая стрелка показывает, куда колесо движется; пунктир — куда оно смотрит. У Trailing разница ${sgn(w.alpha)}°: шина деформируется и скользит поперёк протектора. Её сила меняет общую силу передней оси. Как в итоге меняется угол машины, зависит также от задней оси и водителя. <button class="ack-guide-button" data-ack-guide>Ackermann в заносе: простое объяснение</button>`}}};
const baseSetValue=setValue;
setValue=function(k,v){baseSetValue(k,v);if(['beta','yaw','speed'].includes(k))resetPose();if(view==='course')$('stage').innerHTML=courseView(result)};
const baseSetScene=setScene;
setScene=function(n){baseSetScene(n);resetPose();render()};
view='bump';resetPose();render();
function courseTick(time){if(!courseFrame)courseFrame=time;const dt=Math.min((time-courseFrame)/1000,.04);courseFrame=time;if(running){movePose(dt);if(view==='course'&&!free&&scene!=='transition')$('stage').innerHTML=courseView(result)}requestAnimationFrame(courseTick)}requestAnimationFrame(courseTick);
